package com.farika.soundflow;
import android.content.*;import java.util.*;import java.io.*;import java.util.concurrent.locks.*;import org.json.*;
/** One writer. Metadata checks are quiet; a distinct phase describes only missing transfers. */
public final class DownloadSync {
 private static final ReentrantLock lock=new ReentrantLock();
 public interface Monitor {boolean cancelled();void progress(String text,int percent);default void transfer(String text,int percent){}default void finished(){}default boolean beforeTransfers(int count){return true;}}
 public static String owner(Context c){return c.getSharedPreferences("profile",0).getString("id","");}
 static void check(Context c,String user,Monitor m)throws IOException{if(Thread.currentThread().isInterrupted()||m.cancelled()||user.isEmpty()||!user.equals(owner(c)))throw new InterruptedIOException("Загрузка приостановлена");}
 public static void announce(Context c,String text){c.sendBroadcast(new Intent(OfflineDownloadService.EVENT).setPackage(c.getPackageName()).putExtra("message",text));}
 private static boolean completeWithArt(Context c,ScApi api,SyncDb db,String owner,String plan,String tid,String art){if(OfflineArt.save(c,api,art)){db.sourceReady(owner,tid);return true;}db.state(owner,plan,tid,"RETRY","ARTWORK_PENDING");db.retry(owner,plan,tid,System.currentTimeMillis()+15*60*1000L);return false;}
 private static boolean eligible(Context c,SyncDb db,OfflineStore store,String owner,String plan,Library.Track t,Library.Track copy,boolean auto,boolean force,long now){if(store.excluded(t.id()))return false;if(copy!=null&&!OfflineQuality.needsRepair(copy,t)&&OfflineArt.available(c,copy.artwork()))return false;if(!force&&!auto&&db.cancelled(owner,plan,t.id()))return false;return force||db.retryAt(owner,plan,t.id())<=now;}
 public static String run(Context c,String owner,String id,String name,String kind,boolean refresh,boolean force,Monitor monitor)throws Exception{return run(c,owner,id,name,kind,refresh,force,monitor,new ScApi(c),new OfflineStore(c));}
 static String run(Context c,String owner,String id,String name,String kind,boolean refresh,boolean force,Monitor source,ScApi api,OfflineStore store)throws Exception{
  final long gate=AutoDownloadGate.ticket(owner,id);final boolean[] transferring={false};Monitor monitor=new Monitor(){public boolean cancelled(){return source.cancelled()||!AutoDownloadGate.current(owner,id,gate);}public void progress(String text,int percent){source.progress(text,percent);}public void transfer(String text,int percent){if(!transferring[0]){DownloadActivityState.begin(owner);transferring[0]=true;}source.transfer(text,percent);}};
  lock.lockInterruptibly();try(SyncDb db=new SyncDb(c)){check(c,owner,monitor);db.ensure(owner,id,name,kind);db.active(owner,id,true);if(Session.get(c).isEmpty()){db.status(owner,id,"Нужен вход. Сохранённые треки не удалены.");throw new IOException("Для загрузки войдите в SoundCloud");}ArrayList<Library.Track> tracks=db.tracks(owner,id);boolean auto=AutoDownloads.enabled(c,owner,id);String activeId="";
   try{if(refresh||tracks.isEmpty()){
    CheckCadence.attempted(c,owner,id);db.status(owner,id,"Проверяем список без уведомления…");monitor.progress("Проверяем список…",-1);ArrayList<Library.Track> fetched=new ArrayList<>();
    if("favorites".equals(kind))fetched=FavoriteLoader.load(next->api.likes(owner,next),new FavoriteLoader.Control(){public void check()throws Exception{DownloadSync.check(c,owner,monitor);}public void progress(int n){monitor.progress("Проверено записей: "+n,-1);}});
    else if("track".equals(kind)){Library.Track t=new Library(c).find("sc:"+id.substring("track:".length()));if(t==null)throw new IOException("Трек не найден");fetched.add(t);}else fetched=api.playlistTracks(id);
    check(c,owner,monitor);db.snapshot(owner,id,fetched);tracks=fetched;if(!"track".equals(kind))new PlaylistCache(c).put(id,name,kind,tracks,true,owner);
   }
   HashMap<String,Library.Track> copies=new HashMap<>();for(Library.Track t:store.list())copies.put(t.id(),t);int needed=0,ordinal=0,ready=0,failed=0;long now=System.currentTimeMillis();for(Library.Track t:tracks)if(eligible(c,db,store,owner,id,t,copies.get(t.id()),auto,force,now))needed++;
   if(needed>0&&!source.beforeTransfers(needed)){for(Library.Track pending:tracks)if(eligible(c,db,store,owner,id,pending,copies.get(pending.id()),auto,force,now))db.state(owner,id,pending.id(),"PENDING","");db.status(owner,id,"Найдены новые загрузки: "+needed+". Очередь сохранена.");return "В очереди: "+needed;}
   for(Library.Track t:tracks){check(c,owner,monitor);Library.Track copy=copies.get(t.id());if(store.excluded(t.id())){db.state(owner,id,t.id(),"REMOVED","");continue;}boolean audioReady=copy!=null&&!OfflineQuality.needsRepair(copy,t);
    if(audioReady&&OfflineArt.available(c,copy.artwork())){db.sourceReady(owner,t.id());ready++;continue;}
    if(!force&&!auto&&db.cancelled(owner,id,t.id()))continue;if(!force&&db.retryAt(owner,id,t.id())>now){failed++;continue;}
    final int index=ordinal++,total=Math.max(1,needed);String label=(index+1)+" / "+total+" · "+t.title;if(audioReady)label="Обложка · "+label;final String progressLabel=label;
    check(c,owner,monitor);if(needed==0&&!source.beforeTransfers(1)){db.state(owner,id,t.id(),"PENDING","");db.status(owner,id,"Найдена загрузка. Очередь сохранена.");return "В очереди: 1";}monitor.transfer(label,index*100/total);db.status(owner,id,"Скачиваем: "+label);
    if(audioReady){if(completeWithArt(c,api,db,owner,id,t.id(),copy.artwork()))ready++;else failed++;monitor.progress(label,(index+1)*100/total);continue;}
    activeId=t.id();db.state(owner,id,t.id(),"RUNNING","");try{for(int attempt=0;;attempt++){try{Library.Track saved=store.save(t,new OfflineStore.Progress(){public boolean cancelled(){return monitor.cancelled()||Thread.currentThread().isInterrupted()||!owner.equals(owner(c));}public void update(int p){monitor.progress(progressLabel,p<0?-1:(index*100+p)/total);}});copies.put(t.id(),saved);break;}catch(Exception error){check(c,owner,monitor);DownloadFault fault=DownloadFault.of(error);if(!fault.retry||attempt>=2||error instanceof ScApi.ApiError&&((ScApi.ApiError)error).retryAfterMs>0)throw error;monitor.progress(label+" · повтор "+(attempt+1),-1);Thread.sleep(1000L*(attempt+1));}}
     if(completeWithArt(c,api,db,owner,id,t.id(),copies.get(t.id()).artwork()))ready++;else failed++;
    }catch(Exception e){check(c,owner,monitor);if(e instanceof ScApi.ApiError&&((ScApi.ApiError)e).status==401){db.active(owner,id,false);db.state(owner,id,t.id(),"BLOCKED","AUTH_401");db.retry(owner,id,t.id(),System.currentTimeMillis()+6*60*60*1000L);db.status(owner,id,"401: обновите вход. Очередь сохранена.");throw e;}failed++;DownloadFault fault=DownloadFault.of(e);db.retry(owner,id,t.id(),System.currentTimeMillis()+Math.max(fault.retry?60000L:6*60*60*1000L,e instanceof ScApi.ApiError?((ScApi.ApiError)e).retryAfterMs:0));db.state(owner,id,t.id(),fault.retry?"RETRY":"BLOCKED",fault.code);}
    activeId="";db.status(owner,id,ready+" / "+tracks.size()+" сохранено · недоступно: "+failed);
   }
   db.active(owner,id,false);String summary=transferring[0]?name+": "+ready+" / "+tracks.size()+" сохранено"+(failed>0?". Не сохранено: "+failed+". Причины — в разделе «Загрузки».":". Готово."):"Проверено без скачивания: "+ready+" / "+tracks.size()+" на устройстве"+(failed>0?" · ожидают повтора: "+failed:"");db.status(owner,id,summary);if(transferring[0])announce(c,summary);return summary;
   }catch(Exception e){if(e instanceof InterruptedIOException||e instanceof InterruptedException){if(!activeId.isEmpty())db.state(owner,id,activeId,AutoDownloadGate.current(owner,id,gate)?"PENDING":"CANCELLED","");db.status(owner,id,"Приостановлено. Готовые треки и очередь сохранены.");}else if(e instanceof ScApi.ApiError)db.status(owner,id,"HTTP "+((ScApi.ApiError)e).status+". Список и очередь сохранены.");else db.status(owner,id,"Не завершено: проверьте сеть, память и доступ.");throw e;}
  }finally{try{source.finished();}finally{if(transferring[0])DownloadActivityState.end(owner);lock.unlock();}}
 }
}
